def summarize_ranges(nums: list[int]) -> str:
    if not nums:
        return ""

    nums = sorted(set(nums))
    result = []
    start = nums[0]

    for i in range(1, len(nums)):
        if nums[i] != nums[i - 1] + 1:
            if nums[i - 1] == start:
                result.append(str(start))
            elif nums[i - 1] == start + 1:
                result.extend([str(start), str(nums[i - 1])])
            else:
                result.append(f"{start}..{nums[i - 1]}")
            start = nums[i]

    if nums[-1] == start:
        result.append(str(start))
    elif nums[-1] == start + 1:
        result.extend([str(start), str(nums[-1])])
    else:
        result.append(f"{start}..{nums[-1]}")

    return ",".join(result)
