from decimal import Decimal
from typing import List, Dict, Tuple

def top_customers(rows: List[Dict[str, str]], n: int) -> List[Tuple[str, float]]:
    customer_totals = {}

    for row in rows:
        customer_name = row.get("customer", "").strip()
        if not customer_name:
            continue

        amount_str = row.get("amount", "").strip()
        try:
            amount = Decimal(amount_str.replace('$', '').replace(',', ''))
        except (ValueError, TypeError):
            continue

        if amount == 0:
            continue

        customer_name_lower = customer_name.lower()
        if customer_name_lower not in customer_totals:
            customer_totals[customer_name_lower] = 0

        customer_totals[customer_name_lower] += amount

    sorted_customers = sorted(
        customer_totals.items(),
        key=lambda item: (-item[1], item[0])
    )

    return [(name, float(total)) for name, total in sorted_customers[:n]]
